#include "stdlib/blas/ext/base/ndarray/dtril.h"
#include "stdlib/blas/ext/base/dtril.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"

/**
* Copies the lower triangular part of a double-precision floating-point matrix to another matrix.
*
* @param arrays    list containing input and output ndarrays
*/
void stdlib_blas_ext_dtril( const struct ndarray *arrays[] ) {
	const struct ndarray *A = arrays[ 0 ];
	const struct ndarray *B = arrays[ 1 ];
	const struct ndarray *k_arr = arrays[ 2 ];

	CBLAS_INT M = stdlib_ndarray_dimension( A, 0 );
	CBLAS_INT N = stdlib_ndarray_dimension( A, 1 );

	// Extract the scalar diagonal offset:
	CBLAS_INT k = (CBLAS_INT)*(int64_t *)stdlib_ndarray_data( k_arr );

	API_SUFFIX(stdlib_strided_dtril_ndarray)( M, N, k, (const double *)stdlib_ndarray_data( A ), stdlib_ndarray_stride_elements( A, 0 ), stdlib_ndarray_stride_elements( A, 1 ), stdlib_ndarray_offset_elements( A ), (double *)stdlib_ndarray_data( B ), stdlib_ndarray_stride_elements( B, 0 ), stdlib_ndarray_stride_elements( B, 1 ), stdlib_ndarray_offset_elements( B ) );
}
